import React, { useState, useEffect } from "react";
import "./App.css";
import {
  FaFacebookF,
  FaInstagram,
  FaYoutube
} from "react-icons/fa";

const API_URL = "http://localhost:8000";

export default function App() {
  const [vista, setVista] = useState("home");

  // Estados para empleados
  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({
    nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: ""
  });
  const [empleadoCargado, setEmpleadoCargado] = useState(false);

  // Estados para períodos
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({
    mes: 1, año: 2026, fecha_corte: "", total_general: 0
  });
  const [periodoCargado, setPeriodoCargado] = useState(false);

  // Estados para planillas
  const [planillas, setPlanillas] = useState([]);
  const [nuevaPlanilla, setNuevaPlanilla] = useState({
    periodo_id: "",
    empleado_id: "",
    sueldo_base: 0,
    horas_extras_diurnas: 0,
    horas_extras_nocturnas: 0,
    horas_nocturnas: 0,
    subsidio_alimentacion: 0,
    bono_extra: 0,
    aplica_nocturnidad: false,
    quincena25_aplica: false
  });

  // Cargar datos al iniciar (con ordenamiento de períodos)
  useEffect(() => {
    const cargarDatos = async () => {
      try {
        const [resEmp, resPer, resPla] = await Promise.all([
          fetch(`${API_URL}/empleado`),
          fetch(`${API_URL}/periodo`),
          fetch(`${API_URL}/planilla`)
        ]);
        if (resEmp.ok) {
          const data = await resEmp.json();
          setEmpleados(data);
        }
        if (resPer.ok) {
          const data = await resPer.json();
          // Ordenar períodos por fecha de corte (menor a mayor)
          data.sort((a, b) => new Date(a.fecha_corte) - new Date(b.fecha_corte));
          setPeriodos(data);
        }
        if (resPla.ok) {
          const data = await resPla.json();
          setPlanillas(data);
        }
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };
    cargarDatos();
  }, []);

  // ---- CRUD EMPLEADOS ----
  const crearEmpleado = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/empleado/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados([...empleados, data]);
        limpiarFormularioEmpleado();
        alert("Empleado creado exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo crear el empleado"}`);
      }
    } catch (error) {
      console.error("Error al crear empleado:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarEmpleado = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar este empleado?")) return;
    try {
      const res = await fetch(`${API_URL}/empleado/${id}`, { method: "DELETE" });
      if (res.ok) {
        setEmpleados(empleados.filter(emp => emp.id !== id));
        alert("Empleado eliminado");
      } else {
        alert("Error al eliminar");
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
    }
  };

  const cargarEmpleado = (emp) => {
    setNuevoEmpleado({
      nombre: emp.nombre,
      area: emp.area,
      puesto: emp.puesto,
      salario_mensual: emp.salario_mensual,
      fecha_ingreso: emp.fecha_ingreso
    });
    setEmpleadoCargado(true);
  };

  const limpiarFormularioEmpleado = () => {
    setNuevoEmpleado({ nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: "" });
    setEmpleadoCargado(false);
  };

  // ---- CRUD PERIODOS ----
  const crearPeriodo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/periodo/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoPeriodo),
      });
      if (res.ok) {
        const data = await res.json();
        const nuevosPeriodos = [...periodos, data];
        nuevosPeriodos.sort((a, b) => new Date(a.fecha_corte) - new Date(b.fecha_corte));
        setPeriodos(nuevosPeriodos);
        limpiarFormularioPeriodo();
        alert("Período creado exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo crear el período"}`);
      }
    } catch (error) {
      console.error("Error al crear periodo:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarPeriodo = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar este período? Si tiene planillas asociadas, no se podrá eliminar.")) return;
    try {
      const res = await fetch(`${API_URL}/periodo/${id}`, { method: "DELETE" });
      if (res.ok) {
        setPeriodos(periodos.filter(per => per.id !== id));
        alert("Período eliminado exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo eliminar el período"}`);
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
      alert("Error de conexión con el backend");
    }
  };

  const cargarPeriodo = (per) => {
    setNuevoPeriodo({
      mes: per.mes,
      año: per.año,
      fecha_corte: per.fecha_corte,
      total_general: per.total_general || 0
    });
    setPeriodoCargado(true);
  };

  const limpiarFormularioPeriodo = () => {
    setNuevoPeriodo({ mes: 1, año: 2026, fecha_corte: "", total_general: 0 });
    setPeriodoCargado(false);
  };

  const generarProximoPeriodo = () => {
    if (periodos.length === 0) {
      setNuevoPeriodo({
        mes: 1,
        año: 2026,
        fecha_corte: "2026-01-31",
        total_general: 0
      });
      return;
    }
    const ultimo = periodos.reduce((a, b) => a.fecha_corte > b.fecha_corte ? a : b);
    const fecha = new Date(ultimo.fecha_corte);
    let mes = fecha.getMonth() + 2;
    let año = fecha.getFullYear();
    if (mes > 12) {
      mes = 1;
      año += 1;
    }
    const ultimoDia = new Date(año, mes, 0).getDate();
    const fechaCorte = `${año}-${String(mes).padStart(2, '0')}-${String(ultimoDia).padStart(2, '0')}`;
    setNuevoPeriodo({
      mes: mes,
      año: año,
      fecha_corte: fechaCorte,
      total_general: 0
    });
    setPeriodoCargado(false);
  };

  // ---- CRUD PLANILLAS ----
  const crearPlanilla = async (e) => {
    e.preventDefault();
    if (!nuevaPlanilla.periodo_id || !nuevaPlanilla.empleado_id) {
      alert("Debes seleccionar un período y un empleado");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/planilla/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          periodo_id: parseInt(nuevaPlanilla.periodo_id),
          empleado_id: parseInt(nuevaPlanilla.empleado_id),
          sueldo_base: nuevaPlanilla.sueldo_base,
          horas_extras_diurnas: nuevaPlanilla.horas_extras_diurnas,
          horas_extras_nocturnas: nuevaPlanilla.horas_extras_nocturnas,
          horas_nocturnas: nuevaPlanilla.horas_nocturnas,
          subsidio_alimentacion: nuevaPlanilla.subsidio_alimentacion,
          bono_extra: nuevaPlanilla.bono_extra,
          aplica_nocturnidad: nuevaPlanilla.aplica_nocturnidad,
          quincena25_aplica: nuevaPlanilla.quincena25_aplica
        }),
      });
      if (res.ok) {
        const data = await res.json();
        setPlanillas([...planillas, data]);
        setNuevaPlanilla({
          periodo_id: "",
          empleado_id: "",
          sueldo_base: 0,
          horas_extras_diurnas: 0,
          horas_extras_nocturnas: 0,
          horas_nocturnas: 0,
          subsidio_alimentacion: 0,
          bono_extra: 0,
          aplica_nocturnidad: false,
          quincena25_aplica: false
        });
        alert("Planilla registrada exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo registrar la planilla"}`);
      }
    } catch (error) {
      console.error("Error al crear planilla:", error);
      alert("Error de conexión con el backend");
    }
  };

  // ---- RENDERIZADO DE PÁGINAS ----
  const renderHome = () => (
    <>
      <section className="hero">
        <div className="overlay">
          <h1>
            Bienvenido, Equipo de Recursos Humanos
            <br />
            <span style={{ fontSize: "28px" }}>Control de Planillas Texaco</span>
          </h1>
        </div>
      </section>
      <section style={{ padding: "40px 20px", background: "white" }}>
        <div style={{ maxWidth: "1200px", margin: "auto", display: "flex", flexWrap: "wrap", gap: "30px", alignItems: "center" }}>
          <div style={{ flex: 1, minWidth: "280px" }}>
            <h2 style={{ color: "#d71920" }}>Texaco El Salvador</h2>
            <p style={{ fontSize: "18px", lineHeight: "1.6" }}>
              Somos una empresa líder en la distribución de combustibles y lubricantes en El Salvador. 
              Con más de 50 años de experiencia, ofrecemos productos de la más alta calidad y un servicio 
              excepcional a nuestros clientes.
            </p>
            <p><strong>Misión:</strong> Proveer soluciones energéticas confiables y sostenibles.</p>
            <p><strong>Visión:</strong> Ser la empresa de energía preferida en la región.</p>
          </div>
          <div style={{ flex: 1, minWidth: "280px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
            <img src="https://images.unsplash.com/photo-1596496181871-9681eacf9764?w=300&h=200&fit=crop" alt="Gasolinera" style={{ width: "100%", height: "150px", objectFit: "cover", borderRadius: "8px" }} />
            <img src="https://images.unsplash.com/photo-1566577739112-5180d4bf9390?w=300&h=200&fit=crop" alt="Servicio" style={{ width: "100%", height: "150px", objectFit: "cover", borderRadius: "8px" }} />
            <img src="https://images.unsplash.com/photo-1542652693-0d9f5b4fdb0c?w=300&h=200&fit=crop" alt="Combustible" style={{ width: "100%", height: "150px", objectFit: "cover", borderRadius: "8px" }} />
            <img src="https://images.unsplash.com/photo-1513828583688-c52646db42da?w=300&h=200&fit=crop" alt="Estación" style={{ width: "100%", height: "150px", objectFit: "cover", borderRadius: "8px" }} />
          </div>
        </div>
      </section>
      <section style={{ background: "#efefef", padding: "40px 20px", textAlign: "center" }}>
        <h2 style={{ marginBottom: "20px" }}>Nuestros Servicios</h2>
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "20px", maxWidth: "1000px", margin: "auto" }}>
          <div style={{ background: "white", padding: "20px", borderRadius: "8px", flex: "1 1 200px" }}>
            <h3>⛽ Combustibles</h3>
            <p>Gasolina, diésel y gas licuado de alta calidad.</p>
          </div>
          <div style={{ background: "white", padding: "20px", borderRadius: "8px", flex: "1 1 200px" }}>
            <h3>🔧 Lubricantes</h3>
            <p>Aceites y grasas para todo tipo de vehículos.</p>
          </div>
          <div style={{ background: "white", padding: "20px", borderRadius: "8px", flex: "1 1 200px" }}>
            <h3>🛠️ Mantenimiento</h3>
            <p>Servicios de mecánica y alineación.</p>
          </div>
          <div style={{ background: "white", padding: "20px", borderRadius: "8px", flex: "1 1 200px" }}>
            <h3>💳 Pagos</h3>
            <p>Aceptamos tarjetas de crédito y aplicaciones móviles.</p>
          </div>
        </div>
      </section>
      <section className="cta">
        <h2>Accede al control de planillas del sistema</h2>
        <button className="cta-btn" onClick={() => setVista("empleados")}>Ir a Empleados →</button>
      </section>
    </>
  );

  const renderEmpleados = () => (
    <>
      <section className="hero" style={{ height: "250px" }}>
        <div className="overlay">
          <h1 style={{ fontSize: "36px" }}>Gestión de Empleados</h1>
        </div>
      </section>
      <div style={{ padding: "40px 20px", background: "#efefef", display: "flex", justifyContent: "center" }}>
        <div style={{ maxWidth: "800px", width: "100%", background: "white", padding: "30px", borderRadius: "8px" }}>
          <h2 style={{ textAlign: "center", color: "#d71920", marginBottom: "20px" }}>
            {empleadoCargado ? "Editar Empleado" : "Agregar Nuevo Empleado"}
          </h2>
          <form onSubmit={crearEmpleado}>
            <input type="text" placeholder="Nombre" value={nuevoEmpleado.nombre} onChange={e => setNuevoEmpleado({...nuevoEmpleado, nombre: e.target.value})} required />
            <input type="text" placeholder="Área" value={nuevoEmpleado.area} onChange={e => setNuevoEmpleado({...nuevoEmpleado, area: e.target.value})} required />
            <input type="text" placeholder="Puesto" value={nuevoEmpleado.puesto} onChange={e => setNuevoEmpleado({...nuevoEmpleado, puesto: e.target.value})} required />
            <input type="number" step="0.01" placeholder="Salario mensual" value={nuevoEmpleado.salario_mensual} onChange={e => setNuevoEmpleado({...nuevoEmpleado, salario_mensual: parseFloat(e.target.value)})} required />
            <input type="date" placeholder="Fecha ingreso" value={nuevoEmpleado.fecha_ingreso} onChange={e => setNuevoEmpleado({...nuevoEmpleado, fecha_ingreso: e.target.value})} required />
            <div style={{ display: "flex", gap: "10px" }}>
              <button type="submit" style={{ flex: 1 }}>
                {empleadoCargado ? "Actualizar Empleado" : "Guardar Empleado"}
              </button>
              {empleadoCargado && (
                <button type="button" onClick={limpiarFormularioEmpleado} style={{ background: "#666", flex: 1 }}>
                  Cancelar Edición
                </button>
              )}
            </div>
          </form>
          <hr style={{ margin: "30px 0" }} />
          <h3 style={{ textAlign: "center", marginBottom: "15px" }}>Lista de Empleados</h3>
          <ul style={{ listStyle: "none", padding: 0 }}>
            {empleados.map(emp => (
              <li key={emp.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px", borderBottom: "1px solid #eee" }}>
                <span style={{ fontWeight: "bold" }}>{emp.nombre}</span>
                <div style={{ display: "flex", gap: "8px" }}>
                  <button onClick={() => cargarEmpleado(emp)} style={{ background: "#007bff", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                    Cargar
                  </button>
                  <button onClick={() => eliminarEmpleado(emp.id)} style={{ background: "#d71920", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                    Eliminar
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </>
  );

  const renderPeriodos = () => (
    <>
      <section className="hero" style={{ height: "250px" }}>
        <div className="overlay">
          <h1 style={{ fontSize: "36px" }}>Gestión de Períodos</h1>
        </div>
      </section>
      <div style={{ padding: "40px 20px", background: "#efefef", display: "flex", justifyContent: "center" }}>
        <div style={{ maxWidth: "800px", width: "100%", background: "white", padding: "30px", borderRadius: "8px" }}>
          <h2 style={{ textAlign: "center", color: "#d71920", marginBottom: "20px" }}>
            {periodoCargado ? "Editar Período" : "Agregar Nuevo Período"}
          </h2>
          <form onSubmit={crearPeriodo}>
            <input type="number" placeholder="Mes (1-12)" value={nuevoPeriodo.mes} onChange={e => setNuevoPeriodo({...nuevoPeriodo, mes: parseInt(e.target.value)})} required />
            <input type="number" placeholder="Año" value={nuevoPeriodo.año} onChange={e => setNuevoPeriodo({...nuevoPeriodo, año: parseInt(e.target.value)})} required />
            <input type="date" placeholder="Fecha corte (YYYY-MM-DD)" value={nuevoPeriodo.fecha_corte} onChange={e => setNuevoPeriodo({...nuevoPeriodo, fecha_corte: e.target.value})} required />
            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
              <button type="submit" style={{ flex: 1 }}>
                {periodoCargado ? "Actualizar Período" : "Guardar Período"}
              </button>
              {periodoCargado && (
                <button type="button" onClick={limpiarFormularioPeriodo} style={{ background: "#666", flex: 1 }}>
                  Cancelar Edición
                </button>
              )}
              <button type="button" onClick={generarProximoPeriodo} style={{ background: "#28a745", flex: 1 }}>
                Generar Próximo Período
              </button>
            </div>
          </form>
          <hr style={{ margin: "30px 0" }} />
          <h3 style={{ textAlign: "center", marginBottom: "15px" }}>Lista de Períodos</h3>
          <ul style={{ listStyle: "none", padding: 0 }}>
            {periodos.map(per => (
              <li key={per.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px", borderBottom: "1px solid #eee" }}>
                <span><strong>Mes {per.mes}/{per.año}</strong> - Corte: {per.fecha_corte} {per.total_general > 0 && `(Total: $${per.total_general})`}</span>
                <div style={{ display: "flex", gap: "8px" }}>
                  <button onClick={() => cargarPeriodo(per)} style={{ background: "#007bff", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                    Cargar
                  </button>
                  <button onClick={() => eliminarPeriodo(per.id)} style={{ background: "#d71920", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                    Eliminar
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </>
  );

  const renderPlanillas = () => (
    <>
      <section className="hero" style={{ height: "200px" }}>
        <div className="overlay">
          <h1 style={{ fontSize: "32px" }}>Registro de Planillas</h1>
          <p style={{ color: "#ddd", marginTop: "8px" }}>
            Ingresa los datos del empleado y las horas trabajadas
          </p>
        </div>
      </section>

      <div style={{ padding: "30px 20px", background: "#f5f5f5" }}>
        <div style={{ maxWidth: "1200px", margin: "auto" }}>
          {/* Tarjeta del formulario */}
          <div style={{
            background: "white",
            borderRadius: "16px",
            boxShadow: "0 8px 30px rgba(0,0,0,0.08)",
            padding: "30px 35px",
            marginBottom: "30px"
          }}>
            <h2 style={{ marginBottom: "25px", color: "#d71920", fontSize: "24px" }}>
              📝 Registrar Nueva Planilla
            </h2>

            <form onSubmit={crearPlanilla}>
              {/* Fila 1: Período y Empleado */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Período</label>
                  <select
                    value={nuevaPlanilla.periodo_id}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, periodo_id: e.target.value})}
                    required
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  >
                    <option value="">Seleccione período</option>
                    {periodos.map(per => (
                      <option key={per.id} value={per.id}>
                        Período {per.mes}/{per.año} (corte {per.fecha_corte})
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Empleado</label>
                  <select
                    value={nuevaPlanilla.empleado_id}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, empleado_id: e.target.value})}
                    required
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  >
                    <option value="">Seleccione empleado</option>
                    {empleados.map(emp => (
                      <option key={emp.id} value={emp.id}>
                        {emp.nombre} - {emp.puesto}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Fila 2: Sueldo base y Subsidio */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Sueldo base mensual (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    placeholder="Ej: 650.00"
                    value={nuevaPlanilla.sueldo_base}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, sueldo_base: parseFloat(e.target.value)})}
                    required
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Subsidio de alimentación (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    placeholder="Ej: 30.00"
                    value={nuevaPlanilla.subsidio_alimentacion}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, subsidio_alimentacion: parseFloat(e.target.value)})}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
              </div>

              {/* Fila 3: Horas (3 columnas) */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Horas extra diurnas</label>
                  <input
                    type="number"
                    step="0.5"
                    placeholder="Ej: 45"
                    value={nuevaPlanilla.horas_extras_diurnas}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_diurnas: parseFloat(e.target.value)})}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Horas extra nocturnas</label>
                  <input
                    type="number"
                    step="0.5"
                    placeholder="Ej: 25"
                    value={nuevaPlanilla.horas_extras_nocturnas}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_nocturnas: parseFloat(e.target.value)})}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Horas nocturnas normales</label>
                  <input
                    type="number"
                    step="0.5"
                    placeholder="Ej: 78"
                    value={nuevaPlanilla.horas_nocturnas}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_nocturnas: parseFloat(e.target.value)})}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
              </div>

              {/* Fila 4: Bono y opciones */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Bono extra (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    placeholder="Ej: 0.00"
                    value={nuevaPlanilla.bono_extra}
                    onChange={e => setNuevaPlanilla({...nuevaPlanilla, bono_extra: parseFloat(e.target.value)})}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: "8px", justifyContent: "center" }}>
                  <label style={{ fontWeight: "500" }}>
                    <input
                      type="checkbox"
                      checked={nuevaPlanilla.aplica_nocturnidad}
                      onChange={e => setNuevaPlanilla({...nuevaPlanilla, aplica_nocturnidad: e.target.checked})}
                      style={{ marginRight: "8px" }}
                    />
                    Aplica nocturnidad (recargo adicional)
                  </label>
                  <label style={{ fontWeight: "500" }}>
                    <input
                      type="checkbox"
                      checked={nuevaPlanilla.quincena25_aplica}
                      onChange={e => setNuevaPlanilla({...nuevaPlanilla, quincena25_aplica: e.target.checked})}
                      style={{ marginRight: "8px" }}
                    />
                    Pagar Quincena 25 (50% del sueldo base, solo si ≤ $1,500)
                  </label>
                </div>
              </div>

              {/* Botones */}
              <div style={{ display: "flex", gap: "12px", marginTop: "10px" }}>
                <button type="submit" style={{
                  background: "#d71920",
                  color: "white",
                  border: "none",
                  padding: "12px 32px",
                  borderRadius: "30px",
                  fontSize: "16px",
                  fontWeight: "bold",
                  cursor: "pointer",
                  transition: "0.2s",
                  flex: 1
                }}>
                  Registrar Planilla
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setNuevaPlanilla({
                      periodo_id: "",
                      empleado_id: "",
                      sueldo_base: 0,
                      horas_extras_diurnas: 0,
                      horas_extras_nocturnas: 0,
                      horas_nocturnas: 0,
                      subsidio_alimentacion: 0,
                      bono_extra: 0,
                      aplica_nocturnidad: false,
                      quincena25_aplica: false
                    });
                  }}
                  style={{
                    background: "#6c757d",
                    color: "white",
                    border: "none",
                    padding: "12px 32px",
                    borderRadius: "30px",
                    fontSize: "16px",
                    cursor: "pointer",
                  }}
                >
                  Limpiar
                </button>
              </div>
            </form>
          </div>

          {/* Tabla de planillas registradas */}
          <div style={{
            background: "white",
            borderRadius: "16px",
            boxShadow: "0 8px 30px rgba(0,0,0,0.08)",
            padding: "20px 25px",
            overflowX: "auto"
          }}>
            <h3 style={{ marginBottom: "15px", color: "#333" }}>📋 Planillas Registradas</h3>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13px" }}>
              <thead>
                <tr style={{ backgroundColor: "#f2f2f2" }}>
                  <th style={{ padding: "10px 8px", textAlign: "left" }}>ID</th>
                  <th style={{ padding: "10px 8px", textAlign: "left" }}>Empleado</th>
                  <th style={{ padding: "10px 8px", textAlign: "left" }}>Período</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Sueldo</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Hrs Ext D</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Monto Ext D</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Hrs Ext N</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Monto Ext N</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Hrs Noc</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Monto Noc</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Subsidio</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Bono</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Aguinaldo</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Q.25</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Total Ingresos</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>ISSS</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>AFP</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>ISR</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Total Deducc.</th>
                  <th style={{ padding: "10px 8px", textAlign: "right" }}>Neto</th>
                </tr>
              </thead>
              <tbody>
                {planillas.map(pl => {
                  const emp = empleados.find(e => e.id === pl.empleado_id);
                  const per = periodos.find(p => p.id === pl.periodo_id);
                  return (
                    <tr key={pl.id}>
                      <td style={{ padding: "8px 8px", textAlign: "left" }}>{pl.id}</td>
                      <td style={{ padding: "8px 8px", textAlign: "left" }}>{emp ? emp.nombre : "?"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "left" }}>{per ? `${per.mes}/${per.año}` : "?"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.sueldo_base?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>{pl.horas_extras_diurnas ?? "0"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_horas_extras_diurnas?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>{pl.horas_extras_nocturnas ?? "0"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_horas_extras_nocturnas?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>{pl.horas_nocturnas ?? "0"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_horas_nocturnas?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.subsidio_alimentacion?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.bono_extra?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_aguinaldo?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_quincena25?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}><strong>${pl.total_ingresos?.toFixed(2) ?? "0.00"}</strong></td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_isss?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_afp?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.monto_isr?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}>${pl.total_deducciones?.toFixed(2) ?? "0.00"}</td>
                      <td style={{ padding: "8px 8px", textAlign: "right" }}><strong>${pl.monto_neto?.toFixed(2) ?? "0.00"}</strong></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div className="app">
      <header className="navbar">
        <div className="logo-container">
          <div className="logo-circle">★</div>
          <span className="logo-text">TEXACO</span>
        </div>
        <nav className="nav-links">
          <a href="#" onClick={() => { setVista("home"); limpiarFormularioEmpleado(); limpiarFormularioPeriodo(); }}>Inicio</a>
          <a href="#" onClick={() => { setVista("empleados"); limpiarFormularioPeriodo(); }}>Empleados</a>
          <a href="#" onClick={() => { setVista("periodos"); limpiarFormularioEmpleado(); }}>Períodos</a>
          <a href="#" onClick={() => setVista("planillas")}>Planillas</a>
          <a href="#">Prestaciones</a>
          <a href="#">Ausencias</a>
        </nav>
        <div className="right-section">
          <div className="social-icons">
            <FaFacebookF />
            <FaInstagram />
            <FaYoutube />
          </div>
        </div>
      </header>

      {vista === "home" && renderHome()}
      {vista === "empleados" && renderEmpleados()}
      {vista === "periodos" && renderPeriodos()}
      {vista === "planillas" && renderPlanillas()}

      <footer className="footer">
        © 2026 Texaco El Salvador - Sistema de Control de Planillas
      </footer>
    </div>
  );
}
